const PID = '9933660066825e9a8005c8.58526829';
const out = [];
for (let p = 1; p <= 3; p++) { out.push({ json: { project_id: PID, page: p, page_size: 200 } }); }
return out;

const DRY_RUN = $('Config').first().json.dry_run;
const LOC = ['ms','lv','lt','et','th','fr','nl','no','pt','sv','it','da','ko','pl','es','de','hu','ro','hr','fil','sk','uk','cs','fi','sl','vi','el','tr','id'];
const TAG = /<\s*\/?\s*[a-zA-Z][^<>]*>/g;

function toks(s) { const o = []; let m; TAG.lastIndex = 0;
  while ((m = TAG.exec(s)) !== null) { o.push({ raw: m[0], at: m.index, end: m.index + m[0].length }); } return o; }
function strip(s) { return s.replace(/<\s*\/?\s*[a-zA-Z][^<>]*>/g, ''); }
function nm(r) { const m = /^<\s*\/?\s*([a-zA-Z][a-zA-Z0-9]*)/.exec(r); return m ? m[1].toLowerCase() : ''; }
function cl(r) { return /^<\s*\//.test(r); }
function namesig(t) { const a = []; for (const x of t) { a.push((cl(x.raw) ? '/' : '') + nm(x.raw)); } return a.join('|'); }
function exactsig(t) { const a = []; for (const x of t) { a.push(x.raw); } return a.join('\u0001'); }
function retag(s, t, raws) { let o = ''; let p = 0;
  for (let i = 0; i < t.length; i++) { o += s.slice(p, t[i].at) + raws[i]; p = t[i].end; } return o + s.slice(p); }

function derive(en, tgt) {
  const st = toks(en); const tt = toks(tgt);
  const nsig = namesig(st);
  // 1. Same tag NAME sequence but the tag text differs - Google MT translated the
  //    attributes (<p style="text-align: start"> became <p estilo="...">). Re-anchor
  //    the source tags at the target's own tag positions.
  if (namesig(tt) === nsig) {
    const raws = []; for (const x of st) { raws.push(x.raw); }
    const fixed = retag(tgt, tt, raws);
    if (fixed !== tgt) { return { rule: 'retag_positional', fix: fixed }; }
    return null;
  }
  // 2. MT split one <strong> span into several - merge the seams back.
  let cur = tgt;
  for (let i = 0; i < 8; i++) {
    const nw = cur.replace(/<\s*\/\s*strong\s*>([^<>]{0,40}?)<\s*strong\s*>/i, '$1');
    if (nw === cur) { break; }
    cur = nw;
  }
  if (cur !== tgt && namesig(toks(cur)) === nsig) { return { rule: 'merge_split_bold', fix: cur }; }
  // 3. Source wraps the whole string in one pair and has no inner markup; the target
  //    dropped or mangled that wrapper. Only safe when every tag in the target is the
  //    wrapper tag itself, so no legitimate inner markup is destroyed.
  if (st.length === 2 && !cl(st[0].raw) && cl(st[1].raw) && nm(st[0].raw) === nm(st[1].raw)
      && st[0].at === 0 && st[1].end === en.length) {
    let onlySame = true;
    for (const x of tt) { if (nm(x.raw) !== nm(st[0].raw)) { onlySame = false; } }
    if (onlySame) {
      const inner = strip(tgt).replace(/^\s+|\s+$/g, '');
      if (inner.length > 0) { return { rule: 'rewrap_whole', fix: st[0].raw + inner + st[1].raw }; }
    }
  }
  return null;
}

function keyname(k) {
  if (k && typeof k === 'object') { return k.web || k.other || k.ios || k.android || ''; }
  if (typeof k === 'string') { return k; } return '';
}

const res = $input.all();
const out = [];
const failed = [];
const masked = [];
const st = { pages: res.length, keys: 0, archived: 0, no_defect: 0, fixable: 0,
             needs_linguist: 0, rejected_by_gate: 0, rules: {}, by_locale: {},
             merge_hiding_split_word: 0, dry_run: DRY_RUN };

// A tag boundary sitting inside a word means the MT broke the word as well as the markup.
function splitsWord(t) {
  const re = /<\s*\/?\s*[a-zA-Z][^<>]*>/g; let m;
  while ((m = re.exec(t)) !== null) {
    const before = t.slice(0, m.index); const after = t.slice(m.index + m[0].length);
    if (before.length === 0) { continue; }
    const bc = before.charAt(before.length - 1);
    if (!/[A-Za-z\u00C0-\u024F]/.test(bc)) { continue; }
    if (/^[a-z\u00DF-\u024F]/.test(after)) { return true; }
    if (/^ [a-z\u00DF-\u024F]/.test(after)) { return true; }
  }
  return false;
}

for (const it of res) {
  const body = (it.json || {}).body;
  if (!body || !Array.isArray(body.keys)) { failed.push('page fetch returned no keys array'); continue; }
  for (const k of body.keys) {
    if (k.is_archived) { st.archived++; continue; }
    st.keys++;
    let en = null; const tg = [];
    for (const tr of (k.translations || [])) {
      const iso = (tr.language_iso || '').toLowerCase();
      if (typeof tr.translation !== 'string') { continue; }
      if (iso === 'en') { en = tr.translation; continue; }
      if (LOC.indexOf(iso) < 0) { continue; }
      tg.push({ iso: iso, tr: tr });
    }
    if (en === null || !en.trim()) { continue; }
    const S = toks(en); const xsig = exactsig(S);
    for (const t of tg) {
      const v = t.tr.translation;
      if (!v || !v.trim()) { continue; }
      // Exact tag TOKENS, not just names: a translated attribute is a real defect.
      if (exactsig(toks(v)) === xsig) { st.no_defect++; continue; }
      const d = derive(en, v);
      if (!d) { st.needs_linguist++; continue; }
      // HARD GATES: not one visible character may change, and the result must
      // reproduce the source tag tokens exactly.
      if (strip(d.fix) !== strip(v)) { st.rejected_by_gate++; continue; }
      if (exactsig(toks(d.fix)) !== xsig) { st.rejected_by_gate++; continue; }
      const hid = (d.rule === 'merge_split_bold' && splitsWord(v));
      if (hid) {
        st.merge_hiding_split_word++;
        masked.push({ key_name: keyname(k.key_name), iso: t.iso, key_id: k.key_id,
          translation_id: t.tr.translation_id });
      }
      st.fixable++;
      st.rules[d.rule] = (st.rules[d.rule] || 0) + 1;
      st.by_locale[t.iso] = (st.by_locale[t.iso] || 0) + 1;
      out.push({ json: {
        do_write: !DRY_RUN,
        project_id: body.project_id, key_id: k.key_id, key_name: keyname(k.key_name),
        iso: t.iso, translation_id: t.tr.translation_id, rule: d.rule,
        hides_split_word: hid,
        was_unverified: !!t.tr.is_unverified, was_reviewed: !!t.tr.is_reviewed,
        before: v, after: d.fix,
        put_body: JSON.stringify({ translation: d.fix, is_unverified: !!t.tr.is_unverified })
      }});
    }
  }
}
if (out.length > 0) { out[0].json.derive_stats = st; out[0].json.derive_failed = failed; out[0].json.masked_list = masked; }
else { out.push({ json: { do_write: false, derive_stats: st, derive_failed: failed, masked_list: masked } }); }
return out;

const reqs = $('Derive Mechanical Fixes').all();
const res = $input.all();
const sent = [];
for (const r of reqs) { if (r.json && r.json.do_write === true) { sent.push(r.json); } }
const ALIGNED = (res.length === sent.length);

const ok = [];
const bad = [];
const reasons = {};
function fail(u, why, detail) {
  reasons[why] = (reasons[why] || 0) + 1;
  bad.push({ kind: 'FAILED', reason: why, detail: (detail || '').slice(0, 160),
    key_name: u.key_name, iso: u.iso, translation_id: u.translation_id });
}
if (ALIGNED) {
  for (let i = 0; i < res.length; i++) {
    const u = sent[i];
    const r = res[i].json || {};
    if (r.error) { fail(u, 'api_error', String(r.error.message || r.error)); continue; }
    const t = r.translation;
    if (!t) { fail(u, 'no_translation_in_response', JSON.stringify(r).slice(0, 160)); continue; }
    // Lokalise echoes the saved record. Only an exact echo counts as written.
    if (t.translation !== u.after) { fail(u, 'echo_mismatch', 'saved value differs from intended'); continue; }
    ok.push({ kind: 'written', key_name: u.key_name, iso: u.iso, rule: u.rule,
      translation_id: u.translation_id, chars_before: u.before.length, chars_after: u.after.length });
  }
}
const byRule = {}; const byIso = {};
for (const o of ok) { byRule[o.rule] = (byRule[o.rule] || 0) + 1; byIso[o.iso] = (byIso[o.iso] || 0) + 1; }
let ds = null;
for (const r of reqs) { if (r.json && r.json.derive_stats) { ds = r.json.derive_stats; } }
const out = [{ json: { kind: 'summary', aligned: ALIGNED, attempted: res.length, intended: sent.length,
  written: ok.length, failed: bad.length, fail_reasons: reasons,
  written_by_rule: byRule, written_by_locale: byIso, derive_stats: ds } }];
if (!ALIGNED) { return [out[0]]; }
for (const b of bad) { out.push({ json: b }); }
for (const o of ok) { out.push({ json: o }); }
return out;
